from fractions import Fraction


def digits_to_number(n):
    """Digits needed to write the page numbers 1 to n."""
    total, d, lo = 0, 1, 1
    while lo <= n:
        hi = min(n, 10 ** d - 1)
        total += (hi - lo + 1) * d
        d, lo = d + 1, 10 ** d
    return total


def calibration(intervals, truths):
    """Share of (low, high) ranges holding their truth, ends included."""
    hits = sum(lo <= t <= hi for (lo, hi), t in zip(intervals, truths))
    return Fraction(hits, len(truths))
